namespace csc_descriptor {
static const char* requestKindName(CSCRequestKind k){switch(k){case CSCRequestKind::VALUE_READ:return "VALUE_READ";case CSCRequestKind::INDEX_READ:return "INDEX_READ";case CSCRequestKind::X_READ:return "X_READ";case CSCRequestKind::DESCRIPTOR_READ:return "DESCRIPTOR_READ";case CSCRequestKind::RESULT_TRANSFER:return "RESULT_TRANSFER";default:return "NONE";}}
static bool requestTraceEnabled(){static bool on=[](){const char*p=std::getenv("CSC_REQUEST_TRACE");return p&&*p&&std::string(p)!="0";}();return on;}
static void requestTrace(uint64_t cycle,const char*event,const DRAMSim::RequestToken&t,unsigned channel,uint64_t address,const char*state){if(requestTraceEnabled())std::cerr<<cycle<<" "<<event<<" "<<t.request_id<<" "<<requestKindName(t.request_kind)<<" "<<channel<<" "<<t.global_bg_id<<" "<<t.worker_id<<" "<<t.sequence_number<<" 0x"<<std::hex<<address<<std::dec<<" "<<state<<"\n";}

CSCDescriptorEngine::CSCDescriptorEngine(uint32_t bg,DRAMSim::PIMBlock*p,Submit s,Address a):global_bg_id_(bg),datapath_(p),legacy_submit_(std::move(s)),address_(std::move(a)){if(bg>=64||!p||!legacy_submit_||!address_)throw std::invalid_argument("CSC engine construction");token_factory_=[this](uint32_t g,CSCRequestKind k,uint64_t seq){DRAMSim::RequestToken t;t.request_id=(uint64_t(g+1)<<48)|seq;t.request_kind=k;t.global_bg_id=g;t.worker_id=g;t.sequence_number=seq;t.client_id=1;t.generation=1;return t;};}
CSCDescriptorEngine::CSCDescriptorEngine(uint32_t bg,DRAMSim::PIMBlock*p,TokenSubmit s,TokenFactory f,Address a):global_bg_id_(bg),datapath_(p),token_submit_(std::move(s)),token_factory_(std::move(f)),address_(std::move(a)){if(bg>=64||!p||!token_submit_||!token_factory_||!address_)throw std::invalid_argument("CSC M5 engine construction");}
CSCDescriptorEngine::CSCDescriptorEngine(uint32_t bg,TokenSubmit s,TokenFactory f,Address a,TargetSubmit ts,TargetStatus tq,TargetPoll tp):global_bg_id_(bg),datapath_(nullptr),target_submit_(std::move(ts)),target_status_(std::move(tq)),target_poll_(std::move(tp)),token_submit_(std::move(s)),token_factory_(std::move(f)),address_(std::move(a)){if(bg>=64||!token_submit_||!token_factory_||!address_||!target_submit_||!target_status_||!target_poll_)throw std::invalid_argument("CSC M6 engine construction");}
bool CSCDescriptorEngine::descriptorValid(const CSCDescriptor&d)const{uint64_t bytes=((uint64_t(d.nnz_count)+7)/8)*32;return d.global_bg_id==global_bg_id_&&d.nnz_count&&d.value_offset_bytes%32==0&&d.row_idx_offset_bytes%32==0&&d.x_slot<image_.packed_x->size()&&d.value_offset_bytes+bytes<=image_.values->size()&&d.row_idx_offset_bytes+bytes<=image_.row_indices->size();}
void CSCDescriptorEngine::validateLaunch()const{if(!image_.values||!image_.row_indices||!image_.descriptors||!image_.packed_x||!sink_)throw std::invalid_argument("null CSC launch view");}
void CSCDescriptorEngine::clearSlot(OperandSlot&s){s=OperandSlot{};}
void CSCDescriptorEngine::launch(const CSCBGImageView&v,std::vector<CSCPartial>*sink){if(busy_||tracker_.acceptedCount())throw std::logic_error("CSC engine already busy");image_=v;sink_=sink;validateLaunch();descriptor_pointer_=remaining_nnz_=chunk_offset_=chunk_index_=0;local_sequence_=maximum_outstanding_=0;done_=false;flush_requested_=flush_completed_=false;error_code_=CSCError::NONE;error_.clear();counters_={};tracker_.reset();clearSlot(x_slot_);clearSlot(value_slot_);clearSlot(index_slot_);if(datapath_)datapath_->resetSIMDCounters();target_operation_valid_=false;target_sequence_=0;incomplete_flush_requested_=false;busy_=true;state_=image_.descriptors->empty()?CSCDescriptorState::DONE:CSCDescriptorState::FETCH_DESCRIPTOR;if(state_==CSCDescriptorState::DONE){busy_=false;done_=true;}}
void CSCDescriptorEngine::fail(CSCError code,const std::string&s){if(state_==CSCDescriptorState::ERROR)return;error_code_=code;error_=s;tracker_.abandonWaiting(counters_.total_execution_cycles);busy_=false;done_=false;flush_completed_=false;state_=CSCDescriptorState::ERROR;}
CSCDescriptorEngine::OperandSlot*CSCDescriptorEngine::slotFor(CSCRequestKind k){if(k==CSCRequestKind::X_READ)return &x_slot_;if(k==CSCRequestKind::VALUE_READ)return &value_slot_;if(k==CSCRequestKind::INDEX_READ)return &index_slot_;return nullptr;}
bool CSCDescriptorEngine::prepare(OperandSlot&s,CSCRequestKind k,uint64_t off){clearSlot(s);s.required=true;s.address=address_(global_bg_id_,k,off);s.token=token_factory_(global_bg_id_,k,++local_sequence_);if(!s.token.valid()){fail(CSCError::INTERNAL_INVARIANT,"request ID exhausted");return false;}if(tracker_.empty()&&tracker_.generation()!=s.token.generation)tracker_.reset(s.token.generation);if(!tracker_.create(s.token,s.address,global_bg_id_/4,counters_.total_execution_cycles)){fail(CSCError::INTERNAL_INVARIANT,tracker_.error());return false;}s.created=true;return true;}
void CSCDescriptorEngine::issueWaiting(){if(hasFailed())return;OperandSlot*slots[3]={&x_slot_,&value_slot_,&index_slot_};for(auto*s:slots){if(!s->required||!s->created||s->accepted||s->ready)continue;if(!tracker_.recordAttempt(s->token.request_id,counters_.total_execution_cycles)){fail(CSCError::INTERNAL_INVARIANT,"invalid submit attempt");return;}bool ok=token_submit_?token_submit_(this,s->token,s->address):legacy_submit_(this,s->token.request_kind,s->address);if(!ok){requestTrace(counters_.total_execution_cycles,"reject",s->token,global_bg_id_/4,s->address,"WAITING_TO_SUBMIT");tracker_.recordRejected(s->token.request_id);counters_.stall_cycles_backpressure++;return;}if(!tracker_.recordAccepted(s->token.request_id,global_bg_id_/4,counters_.total_execution_cycles)){fail(CSCError::INTERNAL_INVARIANT,"request acceptance invariant");return;}requestTrace(counters_.total_execution_cycles,"accept",s->token,global_bg_id_/4,s->address,"ACCEPTED");s->accepted=true;if(s->token.request_kind==CSCRequestKind::X_READ)counters_.x_transactions++;else if(s->token.request_kind==CSCRequestKind::VALUE_READ)counters_.value_transactions++;else counters_.index_transactions++;maximum_outstanding_=std::max<uint64_t>(maximum_outstanding_,tracker_.acceptedCount());return;}if(tracker_.acceptedCount())counters_.stall_cycles_request++;}
void CSCDescriptorEngine::stageCompletion(OperandSlot&s){if(s.token.request_kind==CSCRequestKind::X_READ){if(current_.x_slot>=image_.packed_x->size()){fail(CSCError::MALFORMED_DESCRIPTOR,"packed x changed while request was pending");return;}x_j_=(*image_.packed_x)[current_.x_slot];counters_.x_scalar_loads++;}else if(s.token.request_kind==CSCRequestKind::VALUE_READ)std::memcpy(value_staging_.data(),image_.values->data()+current_.value_offset_bytes+chunk_offset_,32);else if(s.token.request_kind==CSCRequestKind::INDEX_READ)std::memcpy(index_staging_.data(),image_.row_indices->data()+current_.row_idx_offset_bytes+chunk_offset_,32);s.ready=true;s.accepted=false;tracker_.retire(s.token.request_id);}
bool CSCDescriptorEngine::onRequestComplete(unsigned c,const DRAMSim::RequestToken&t,uint64_t cycle){OperandSlot*s=slotFor(t.request_kind);if(!s||!s->created||s->token.request_id!=t.request_id||!tracker_.complete(c,t,cycle)){fail(CSCError::REQUEST_COMPLETION,tracker_.error().empty()?"request token mismatch":tracker_.error());return false;}if(hasFailed()){tracker_.retire(t.request_id);s->accepted=false;s->ready=false;return true;}stageCompletion(*s);if(hasFailed()){tracker_.retire(t.request_id);s->accepted=false;s->ready=false;}return true;}
bool CSCDescriptorEngine::onRequestComplete(unsigned c,uint64_t a,uint64_t cycle){for(auto*s:{&x_slot_,&value_slot_,&index_slot_})if(s->accepted&&s->address==a)return onRequestComplete(c,s->token,cycle);return false;}
void CSCDescriptorEngine::tick(){if(!busy_)return;counters_.busy_cycles++;counters_.total_execution_cycles++;switch(state_){
case CSCDescriptorState::FETCH_DESCRIPTOR:current_=(*image_.descriptors)[descriptor_pointer_];if(!descriptorValid(current_)){fail(CSCError::MALFORMED_DESCRIPTOR,"malformed CSC descriptor at runtime");break;}remaining_nnz_=current_.nnz_count;chunk_offset_=chunk_index_=0;counters_.descriptor_fetches++;if(!prepare(x_slot_,CSCRequestKind::X_READ,uint64_t(current_.x_slot/8)*32)||!prepare(value_slot_,CSCRequestKind::VALUE_READ,current_.value_offset_bytes)||!prepare(index_slot_,CSCRequestKind::INDEX_READ,current_.row_idx_offset_bytes))break;state_=CSCDescriptorState::LOAD_X;break;
case CSCDescriptorState::LOAD_X:issueWaiting();state_=CSCDescriptorState::FETCH_VALUE;break;
case CSCDescriptorState::FETCH_VALUE:issueWaiting();state_=CSCDescriptorState::FETCH_ROW_INDEX;break;
case CSCDescriptorState::FETCH_ROW_INDEX:issueWaiting();state_=CSCDescriptorState::WAIT_OPERANDS;break;
case CSCDescriptorState::WAIT_OPERANDS:issueWaiting();if(x_slot_.ready&&value_slot_.ready&&index_slot_.ready)state_=CSCDescriptorState::SIMD_MUL;break;
case CSCDescriptorState::SIMD_MUL:{valid_count_=std::min<uint32_t>(remaining_nnz_,8);DRAMSim::BurstType values,scalar;for(uint32_t i=0;i<8;i++){values.fp32Data_[i]=0;scalar.fp32Data_[i]=x_j_;result_staging_.fp32Data_[i]=-12345;}std::memcpy(values.fp32Data_,value_staging_.data(),valid_count_*4);if(!target_submit_){auto before=datapath_->simdCounters();datapath_->mul(result_staging_,values,scalar,valid_count_);auto after=datapath_->simdCounters();counters_.invalid_lane_multiplies+=(after.invalid_lane_operand_reads-before.invalid_lane_operand_reads)+(after.invalid_lane_arithmetic_operations-before.invalid_lane_arithmetic_operations);counters_.invalid_lane_writes+=after.invalid_lane_destination_writes-before.invalid_lane_destination_writes;counters_.logical_mul_events++;counters_.total_chunks++;counters_.active_lanes+=valid_count_;counters_.available_lanes+=8;valid_count_==8?counters_.full_chunks++:counters_.tail_chunks++;state_=CSCDescriptorState::EMIT_PARTIALS;break;}if(!target_operation_valid_){target_operation_={};target_operation_.identity.operation_id=(uint64_t(global_bg_id_+1)<<48)|(++target_sequence_);target_operation_.identity.channel=global_bg_id_/4;target_operation_.identity.rank=0;target_operation_.identity.local_bg=global_bg_id_%4;target_operation_.identity.pimblock_mask=DRAMSim::kBGTargetFirstPIMBlock;target_operation_.identity.opcode=DRAMSim::BGTargetedOpcode::MASKED_MUL;target_operation_.identity.worker_id=global_bg_id_;target_operation_.identity.sequence=target_sequence_;target_operation_.identity.generation=tracker_.generation();target_operation_.valid_count=valid_count_;target_operation_.contexts[0].lhs=values;target_operation_.contexts[0].rhs=scalar;target_operation_.contexts[0].valid=true;target_operation_valid_=true;}if(target_submit_(this,target_operation_))state_=CSCDescriptorState::WAIT_TARGET_GRANT;break;}
case CSCDescriptorState::WAIT_TARGET_GRANT:if(target_status_(target_operation_.identity)!=DRAMSim::BGTargetedOperationState::WAITING_FOR_GRANT)state_=CSCDescriptorState::WAIT_TARGET_COMPLETION;break;
case CSCDescriptorState::WAIT_TARGET_COMPLETION:{DRAMSim::BGTargetedCompletion completion;if(!target_poll_(target_operation_.identity,completion))break;if(!(completion.identity==target_operation_.identity)){fail(CSCError::INTERNAL_INVARIANT,"targeted completion identity mismatch");break;}if(completion.completion_cycle<=completion.grant_cycle){fail(CSCError::INTERNAL_INVARIANT,"same-cycle targeted completion");break;}result_staging_=completion.results[0];target_operation_valid_=false;if(incomplete_flush_requested_){state_=CSCDescriptorState::FLUSHING;break;}counters_.logical_mul_events++;counters_.total_chunks++;counters_.active_lanes+=valid_count_;counters_.available_lanes+=8;valid_count_==8?counters_.full_chunks++:counters_.tail_chunks++;state_=CSCDescriptorState::EMIT_PARTIALS;break;}
case CSCDescriptorState::EMIT_PARTIALS:for(uint32_t i=0;i<valid_count_;i++){uint32_t row;std::memcpy(&row,index_staging_.data()+i*4,4);sink_->push_back({row,global_bg_id_,descriptor_pointer_,chunk_index_,i,result_staging_.fp32Data_[i]});counters_.generated_partials++;counters_.emitted_partials++;}state_=CSCDescriptorState::ADVANCE_CHUNK;break;
case CSCDescriptorState::ADVANCE_CHUNK:remaining_nnz_-=valid_count_;chunk_offset_+=32;chunk_index_++;if(remaining_nnz_){clearSlot(value_slot_);clearSlot(index_slot_);if(!prepare(value_slot_,CSCRequestKind::VALUE_READ,current_.value_offset_bytes+chunk_offset_)||!prepare(index_slot_,CSCRequestKind::INDEX_READ,current_.row_idx_offset_bytes+chunk_offset_))break;state_=CSCDescriptorState::WAIT_OPERANDS;}else state_=CSCDescriptorState::NEXT_DESCRIPTOR;break;
case CSCDescriptorState::NEXT_DESCRIPTOR:descriptor_pointer_++;if(descriptor_pointer_<image_.descriptors->size()){clearSlot(x_slot_);clearSlot(value_slot_);clearSlot(index_slot_);state_=CSCDescriptorState::FETCH_DESCRIPTOR;}else finishWork();break;
case CSCDescriptorState::DONE:if(!tracker_.empty()){fail(CSCError::INTERNAL_INVARIANT,"DONE with pending request");break;}busy_=false;done_=true;break;
case CSCDescriptorState::FLUSHING:if(tracker_.empty()){state_=CSCDescriptorState::DONE;busy_=false;done_=true;flush_completed_=true;}break;case CSCDescriptorState::IDLE:case CSCDescriptorState::ERROR:break;}}
void CSCDescriptorEngine::finishWork(){if(!tracker_.terminalAccountingValid()||tracker_.stats().abandoned_waiting_requests){fail(CSCError::INTERNAL_INVARIANT,"successful DONE request accounting invariant");return;}if(flush_requested_){state_=CSCDescriptorState::FLUSHING;busy_=true;}else{state_=CSCDescriptorState::DONE;busy_=false;done_=true;}}
void CSCDescriptorEngine::flush(){if(state_==CSCDescriptorState::ERROR)return;if(state_==CSCDescriptorState::DONE&&flush_completed_)return;flush_requested_=true;if(state_==CSCDescriptorState::IDLE||state_==CSCDescriptorState::DONE){flush_completed_=false;done_=false;busy_=true;state_=CSCDescriptorState::FLUSHING;}}
void CSCDescriptorEngine::flushIncomplete(){if(state_==CSCDescriptorState::ERROR||state_==CSCDescriptorState::DONE)return;flush_requested_=true;incomplete_flush_requested_=true;tracker_.abandonWaiting(counters_.total_execution_cycles);if(state_!=CSCDescriptorState::WAIT_TARGET_COMPLETION)state_=CSCDescriptorState::FLUSHING;busy_=true;}
void CSCDescriptorEngine::reset(){if(tracker_.acceptedCount())throw std::logic_error("reset with pending request");tracker_.reset();clearSlot(x_slot_);clearSlot(value_slot_);clearSlot(index_slot_);target_operation_valid_=false;incomplete_flush_requested_=false;busy_=done_=flush_requested_=flush_completed_=false;error_code_=CSCError::NONE;state_=CSCDescriptorState::IDLE;error_.clear();counters_={};}
struct CSCNativeExecution::Impl{std::shared_ptr<DRAMSim::MultiChannelMemorySystem>mem;std::unique_ptr<PIMAddrManager>addresses;DRAMSim::TransactionCompleteCB*read_cb=nullptr,*write_cb=nullptr;DRAMSim::TokenCompleteCB*token_read_cb=nullptr,*token_write_cb=nullptr;DRAMSim::BurstType burst;};
CSCNativeExecution::CSCNativeExecution(CSCRequestPolicy p):impl_(new Impl),policy_(p){impl_->mem=std::make_shared<DRAMSim::MultiChannelMemorySystem>("ini/HBM2_samsung_2M_16B_x64.ini","system_hbm_csc_fp32.ini",".","csc_native_m5",256*16);if(getConfigParam(UINT,"NUM_CHANS")!=16||getConfigParam(UINT,"NUM_RANKS")!=1||getConfigParam(UINT,"NUM_BANK_GROUPS")!=4||PIMConfiguration::getPIMPrecision()!=FP32)throw std::runtime_error("M5 requires 16ch/1rank/4BG/FP32");impl_->addresses.reset(new PIMAddrManager(16,1));impl_->read_cb=new DRAMSim::Callback<CSCNativeExecution,void,unsigned,uint64_t,uint64_t>(this,&CSCNativeExecution::readComplete);impl_->write_cb=new DRAMSim::Callback<CSCNativeExecution,void,unsigned,uint64_t,uint64_t>(this,&CSCNativeExecution::readComplete);impl_->token_read_cb=new DRAMSim::Callback<CSCNativeExecution,void,unsigned,const DRAMSim::RequestToken&,uint64_t>(this,&CSCNativeExecution::tokenComplete);impl_->token_write_cb=new DRAMSim::Callback<CSCNativeExecution,void,unsigned,const DRAMSim::RequestToken&,uint64_t>(this,&CSCNativeExecution::tokenComplete);impl_->mem->RegisterCallbacks(impl_->read_cb,impl_->write_cb,nullptr);impl_->mem->RegisterTokenCallbacks(impl_->token_read_cb,impl_->token_write_cb);for(uint32_t g=0;g<64;g++){engines_.emplace_back(new CSCDescriptorEngine(g,[this](auto*e,const auto&t,auto a){return submit(e,t,a);},[this](auto g,auto k,auto s){return makeToken(g,k,s);},[this](auto g,auto k,auto o){return addressFor(g,k,o);},[this](auto*e,const auto&op){return submitTarget(e,op);},[this](const auto&id){return targetStatus(id);},[this](const auto&id,auto&completion){return pollTarget(id,completion);}));}}
CSCNativeExecution::~CSCNativeExecution(){delete impl_->read_cb;delete impl_->write_cb;delete impl_->token_read_cb;delete impl_->token_write_cb;}
uint64_t CSCNativeExecution::addressFor(uint32_t g,CSCRequestKind kind,uint64_t offset){uint32_t bank=kind==CSCRequestKind::X_READ?2:(kind==CSCRequestKind::VALUE_READ?0:1);uint32_t base=kind==CSCRequestKind::X_READ?8192:(kind==CSCRequestKind::VALUE_READ?0:4096);unsigned row=base,col=offset/32;return impl_->addresses->addrGenSafe(g/4,0,g%4,bank,row,col);}
DRAMSim::RequestToken CSCNativeExecution::makeToken(uint32_t g,CSCRequestKind k,uint64_t seq){DRAMSim::RequestToken t;if(next_request_id_==std::numeric_limits<uint64_t>::max()){failGlobal(CSCError::INTERNAL_INVARIANT,"request ID exhausted",int32_t(g));return t;}t.request_id=next_request_id_++;t.request_kind=k;t.global_bg_id=g;t.worker_id=g;t.sequence_number=seq;t.client_id=1;t.generation=generation_;return t;}
bool CSCNativeExecution::submit(CSCDescriptorEngine*e,const DRAMSim::RequestToken&t,uint64_t a){if(submit_reject_budget_[e->globalBG()]){submit_reject_budget_[e->globalBG()]--;return false;}if(failed_||(policy_==CSCRequestPolicy::SERIALIZED&&!outstanding_.empty()))return false;if(!impl_->mem->addTransaction(false,a,"CSC_NATIVE_M5",&impl_->burst,t))return false;for(auto&p:outstanding_addresses_)if(p.second==a){execution_stats_.same_address_concurrent_requests++;break;}outstanding_[t.request_id]=e;outstanding_addresses_[t.request_id]=a;return true;}
bool CSCNativeExecution::submitTarget(CSCDescriptorEngine* engine,const DRAMSim::BGTargetedOperation& operation){const auto&id=operation.identity;if(!engine||engine->globalBG()!=id.worker_id||id.channel!=engine->globalBG()/4||id.local_bg!=engine->globalBG()%4||id.rank!=0){failGlobal(CSCError::INTERNAL_INVARIANT,"targeted operation owner mismatch",engine?int32_t(engine->globalBG()):-1);return false;}if(id.channel>=impl_->mem->channels.size())throw std::logic_error("targeted channel mapping corruption");auto*channel=impl_->mem->channels[id.channel];if(!channel->ranks||id.rank>=channel->ranks->size())throw std::logic_error("targeted rank mapping corruption");return channel->ranks->at(id.rank)->pimRank->submitBGTargetedOperation(operation);}
DRAMSim::BGTargetedOperationState CSCNativeExecution::targetStatus(const DRAMSim::BGTargetedIdentity&id)const{if(id.channel>=impl_->mem->channels.size())throw std::logic_error("targeted status channel corruption");auto*channel=impl_->mem->channels[id.channel];if(!channel->ranks||id.rank>=channel->ranks->size())throw std::logic_error("targeted status rank corruption");return channel->ranks->at(id.rank)->pimRank->queryBGTargetedOperation(id.local_bg,id.operation_id);}
bool CSCNativeExecution::pollTarget(const DRAMSim::BGTargetedIdentity&id,DRAMSim::BGTargetedCompletion&completion){if(id.channel>=impl_->mem->channels.size())throw std::logic_error("targeted completion channel corruption");auto*channel=impl_->mem->channels[id.channel];if(!channel->ranks||id.rank>=channel->ranks->size())throw std::logic_error("targeted completion rank corruption");if(!channel->ranks->at(id.rank)->pimRank->pollBGTargetedCompletion(id.local_bg,completion))return false;if(!(completion.identity==id)){failGlobal(CSCError::INTERNAL_INVARIANT,"targeted completion owner mismatch",int32_t(id.worker_id));return false;}return true;}
void CSCNativeExecution::readComplete(unsigned,uint64_t,uint64_t){}
void CSCNativeExecution::tokenComplete(unsigned c,const DRAMSim::RequestToken&t,uint64_t when){auto i=outstanding_.find(t.request_id);if(i==outstanding_.end()){execution_stats_.unknown_completions++;if(!failed_){failed_=true;error_code_=CSCError::REQUEST_COMPLETION;error_message_="unknown M5 completion token";failed_engine_=-1;}return;}auto*e=i->second;if(t.global_bg_id!=e->globalBG()){execution_stats_.unknown_completions++;if(!failed_){failed_=true;error_code_=CSCError::REQUEST_COMPLETION;error_message_="M5 completion owner mismatch";failed_engine_=int32_t(e->globalBG());}}requestTrace(when,"complete",t,c,outstanding_addresses_[t.request_id],"COMPLETED");if(!e->onRequestComplete(c,t,when))latchFailure(*e);outstanding_.erase(i);outstanding_addresses_.erase(t.request_id);execution_stats_.completion_count++;execution_stats_.completed_by_kind[size_t(t.request_kind)]++;execution_stats_.completed_by_bg[t.global_bg_id]++;}
void CSCNativeExecution::launch(const std::array<CSCBGImageView,64>&v,uint32_t rows,uint64_t nnz){if(busy())throw std::logic_error("M5 execution busy");if(generation_==std::numeric_limits<uint32_t>::max()){partials_.clear();rows_=0;nnz_=0;cycle_=host_accumulations_=0;outstanding_.clear();outstanding_addresses_.clear();failed_=flush_requested_=flush_completed_=false;error_code_=CSCError::NONE;failed_engine_=-1;error_message_.clear();execution_stats_={};launched_=true;failGlobal(CSCError::INTERNAL_INVARIANT,"generation exhausted");return;}uint64_t descriptor_nnz=0;for(auto&bg:v){if(!bg.descriptors)throw std::invalid_argument("null M5 descriptor view");for(auto&d:*bg.descriptors)descriptor_nnz+=d.nnz_count;}if(descriptor_nnz!=nnz)throw std::invalid_argument("M5 descriptor NNZ mismatch");partials_.clear();rows_=rows;nnz_=nnz;cycle_=host_accumulations_=0;outstanding_.clear();outstanding_addresses_.clear();generation_++;for(auto&status:result_status_)status=CSCResultStatus::RUNNING;failed_=flush_requested_=flush_completed_=false;error_code_=CSCError::NONE;failed_engine_=-1;error_message_.clear();execution_stats_={};for(uint32_t g=0;g<64;g++){engines_[g]->reset();engines_[g]->launch(v[g],&partials_);}launched_=true;}
void CSCNativeExecution::failGlobal(CSCError code,const std::string&message,int32_t engine){if(failed_)return;failed_=true;error_code_=code;error_message_=message;failed_engine_=engine;}
void CSCNativeExecution::latchFailure(const CSCDescriptorEngine&e){failGlobal(e.errorCode(),e.errorMessage(),int32_t(e.globalBG()));}
void CSCNativeExecution::updateMLP(){uint64_t n=outstanding_.size();execution_stats_.maximum_global_outstanding=std::max(execution_stats_.maximum_global_outstanding,n);if(n)execution_stats_.cycles_with_outstanding_ge_1++;if(n>=2)execution_stats_.cycles_with_outstanding_ge_2++;execution_stats_.outstanding_cycle_integral+=n;std::array<uint64_t,16>ch{};for(auto&p:outstanding_){auto bg=p.second->globalBG();ch[bg/4]++;}for(auto n2:ch)execution_stats_.maximum_outstanding_per_channel=std::max(execution_stats_.maximum_outstanding_per_channel,n2);for(auto&e:engines_)execution_stats_.maximum_outstanding_per_engine=std::max(execution_stats_.maximum_outstanding_per_engine,e->maximumOutstanding());}
void CSCNativeExecution::tick(){if(!launched_||isTerminal())return;impl_->mem->update();cycle_++;for(auto&e:engines_){if(failed_)break;e->tick();if(e->hasFailed())latchFailure(*e);}updateMLP();if(flush_requested_&&isDone())flush_completed_=true;}
bool CSCNativeExecution::busy()const{return launched_&&!isTerminal();}bool CSCNativeExecution::hasPendingTransactions()const{return impl_->mem->hasPendingTransactions();}bool CSCNativeExecution::hasUnconsumedCompletion()const{for(auto&e:engines_)if(e->tracker().pendingCount())return true;return false;}
bool CSCNativeExecution::isTerminal()const{if(!launched_||!outstanding_.empty())return false;if(failed_)return true;for(auto&e:engines_)if(!e->isTerminal())return false;return true;}bool CSCNativeExecution::isDone()const{if(!isTerminal()||failed_)return false;for(auto&e:engines_)if(!e->isDone())return false;return true;}
void CSCNativeExecution::flushBG(uint32_t bg){if(bg>=64)throw std::out_of_range("CSC BG");auto*channel=impl_->mem->channels.at(bg/4);channel->ranks->at(0)->pimRank->flushBG(bg%4);engines_[bg]->flushIncomplete();result_status_[bg]=CSCResultStatus::INCOMPLETE_FLUSHED;}
bool CSCNativeExecution::resetBG(uint32_t bg){if(bg>=64)throw std::out_of_range("CSC BG");auto*channel=impl_->mem->channels.at(bg/4);if(!channel->ranks->at(0)->pimRank->resetBG(bg%4))return false;engines_[bg]->reset();result_status_[bg]=CSCResultStatus::RUNNING;return true;}
void CSCNativeExecution::flush(){flush_requested_=true;bool idle=!launched_;if(idle)launched_=true;for(auto&e:engines_)e->flush();if(idle)for(auto&e:engines_)e->tick();if(isDone())flush_completed_=true;}
bool CSCNativeExecution::resultValid()const{for(auto status:result_status_)if(status==CSCResultStatus::INCOMPLETE_FLUSHED||status==CSCResultStatus::ERROR)return false;return isDone();}
void CSCNativeExecution::reset(){if(!outstanding_.empty())throw std::logic_error("M5 reset with pending request");for(auto&e:engines_)e->reset();partials_.clear();launched_=failed_=flush_requested_=flush_completed_=false;rows_=0;nnz_=0;host_accumulations_=0;error_code_=CSCError::NONE;failed_engine_=-1;error_message_.clear();}
std::vector<float>CSCNativeExecution::hostAccumulate(){if(!isDone())throw std::logic_error("M5 accumulation before successful DONE");std::vector<double>s(rows_);host_accumulations_=0;for(auto&p:partials_){if(p.row_idx>=rows_)throw std::logic_error("M5 partial row range");s[p.row_idx]+=p.value;host_accumulations_++;}std::vector<float>y(rows_);for(size_t i=0;i<y.size();i++)y[i]=float(s[i]);return y;}
CSCExecutionCounters CSCNativeExecution::counters()const{auto t=execution_stats_;for(auto&e:engines_){auto&c=e->counters();t.descriptor_fetches+=c.descriptor_fetches;t.x_scalar_loads+=c.x_scalar_loads;t.x_transactions+=c.x_transactions;t.value_transactions+=c.value_transactions;t.index_transactions+=c.index_transactions;t.logical_mul_events+=c.logical_mul_events;t.full_chunks+=c.full_chunks;t.tail_chunks+=c.tail_chunks;t.total_chunks+=c.total_chunks;t.active_lanes+=c.active_lanes;t.available_lanes+=c.available_lanes;t.invalid_lane_multiplies+=c.invalid_lane_multiplies;t.invalid_lane_writes+=c.invalid_lane_writes;t.generated_partials+=c.generated_partials;t.emitted_partials+=c.emitted_partials;t.stall_cycles_request+=c.stall_cycles_request;t.stall_cycles_backpressure+=c.stall_cycles_backpressure;t.busy_cycles+=c.busy_cycles;auto&s=e->tracker().stats();t.created_requests+=s.created_requests;t.submit_attempts+=s.submit_attempts;t.accepted_requests+=s.issued;t.abandoned_waiting_requests+=s.abandoned_waiting_requests;t.submit_rejections+=s.submit_rejected;t.retry_count+=s.retries;t.unknown_completions+=s.unknown_completions;t.duplicate_completions+=s.duplicate_completions;t.stale_generation_completions+=s.stale_generation_completions;t.request_kind_mismatches+=s.kind_mismatches;t.owner_mismatches+=s.owner_mismatches;t.completion_after_retirement+=s.completion_after_retirement;t.maximum_waiting_to_submit_depth=std::max(t.maximum_waiting_to_submit_depth,s.maximum_waiting_to_submit_depth);for(size_t k=0;k<kCSCRequestKindCount;k++){t.issued_by_kind[k]+=s.issued_by_kind[k];t.abandoned_by_kind[k]+=s.abandoned_by_kind[k];}for(size_t bg=0;bg<kCSCGlobalBGCount;bg++)t.abandoned_by_bg[bg]+=s.abandoned_by_bg[bg];t.issued_by_bg[e->globalBG()]+=s.issued;}for(uint32_t channel=0;channel<impl_->mem->channels.size();++channel){auto*rank=impl_->mem->channels[channel]->ranks->at(0);const auto&s=rank->pimRank->targetedStatistics();for(uint32_t bg=0;bg<4;++bg){uint32_t global=channel*4+bg;t.per_bg_ready_cycles[global]=s.per_bg_ready_cycles[bg];t.per_bg_executing_cycles[global]=s.per_bg_executing_cycles[bg];t.per_bg_grant_wait_cycles[global]=s.per_bg_grant_wait_cycles[bg];t.per_bg_flush_drain_cycles[global]=s.per_bg_flush_drain_cycles[bg];t.per_bg_memory_wait_cycles[global]=engines_[global]->counters().stall_cycles_request;}for(uint32_t block=0;block<8;++block){t.per_pimblock_active_cycles[channel*8+block]=s.per_pimblock_active_cycles[block];t.per_pimblock_targeted_ops[channel*8+block]=s.per_pimblock_targeted_ops[block];}t.rank_targeted_grants+=s.rank_targeted_grants;t.rank_command_bus_stall_cycles+=s.rank_command_bus_stall_cycles;t.rank_resource_conflict_stall_cycles+=s.rank_resource_conflict_stall_cycles;t.rank_mode_drain_cycles+=s.rank_mode_drain_cycles;t.round_robin_skip_count+=s.round_robin_skip_count;}t.host_accumulations=host_accumulations_;t.launch_to_done_cycles=cycle_;t.total_execution_cycles=t.launch_to_done_cycles;if(t.cycles_with_outstanding_ge_1)t.average_outstanding=double(t.outstanding_cycle_integral)/t.cycles_with_outstanding_ge_1;return t;}
}
